import test from "node:test";
import assert from "node:assert/strict";
import { ConflictError, Repository } from "../src/repository.ts";

test("updates require the current revision and conflicts preserve the document", () => {
  const repository = new Repository();
  repository.create("a", { title: "Original" });
  const updated = repository.update("a", { title: "Updated" }, { expected_revision: 1 });
  assert.equal(updated.revision, 2);
  const stored = repository.records.get("a");

  for (const expected_revision of [1, 3]) {
    assert.throws(
      () => repository.update("a", { title: "Rejected" }, { expected_revision }),
      ConflictError,
    );
    assert.strictEqual(repository.records.get("a"), stored);
    assert.deepEqual(repository.records.get("a"), updated);
  }

  const next = repository.update("a", { title: "Next" }, { expected_revision: 2 });
  assert.equal(next.revision, 3);
});

test("successful updates isolate nested input and returned bodies", () => {
  const repository = new Repository();
  repository.create("a", {});
  const body = { nested: { title: "Updated" }, tags: ["original"] };
  const updated = repository.update("a", body, { expected_revision: 1 });
  body.nested.title = "Changed input";
  body.tags.push("input");
  assert.deepEqual(updated.body, { nested: { title: "Updated" }, tags: ["original"] });
  updated.body.nested.title = "Changed return";
  updated.body.tags.push("return");
  assert.deepEqual(repository.records.get("a"), {
    id: "a",
    body: { nested: { title: "Updated" }, tags: ["original"] },
    revision: 2,
  });
});
